using NUnit.Framework;
using UnityEngine;
using UnityEngine.Rendering;
using LighFight.Runtime;
namespace LighFight.Tests {
 public sealed class ShadowTogglePreservationTests {
  GameObject root;Material material,replacement;Texture2D normal,metal;
  [SetUp]public void Setup(){root=new GameObject("shadow flags ownership");material=new Material(Shader.Find("Standard"));replacement=new Material(Shader.Find("Standard"));normal=new Texture2D(1,1);metal=new Texture2D(1,1);material.SetTexture("_BumpMap",normal);material.SetTexture("_MetallicGlossMap",metal);material.EnableKeyword("_NORMALMAP");material.EnableKeyword("_METALLICGLOSSMAP");}
  [TearDown]public void Cleanup(){Object.DestroyImmediate(root);Object.DestroyImmediate(material);Object.DestroyImmediate(replacement);Object.DestroyImmediate(normal);Object.DestroyImmediate(metal);}
  MeshRenderer Child(string name,ShadowCastingMode casting,bool receiving){var go=new GameObject(name);go.transform.SetParent(root.transform);var r=go.AddComponent<MeshRenderer>();r.sharedMaterial=material;r.shadowCastingMode=casting;r.receiveShadows=receiving;return r;}
  [Test]public void OffKeepsExactPbrMaterialShaderMapsAndKeywords(){var r=Child("PBR",ShadowCastingMode.TwoSided,true);var toggle=root.AddComponent<ShadowlessFighterMaterials>();var shader=material.shader;toggle.Apply();Assert.AreSame(material,r.sharedMaterial);Assert.AreSame(shader,r.sharedMaterial.shader);Assert.AreSame(normal,r.sharedMaterial.GetTexture("_BumpMap"));Assert.AreSame(metal,r.sharedMaterial.GetTexture("_MetallicGlossMap"));Assert.IsTrue(r.sharedMaterial.IsKeywordEnabled("_NORMALMAP"));Assert.IsTrue(r.sharedMaterial.IsKeywordEnabled("_METALLICGLOSSMAP"));Assert.AreEqual(ShadowCastingMode.Off,r.shadowCastingMode);Assert.IsFalse(r.receiveShadows);}
  [Test]public void RestoreReturnsAuthoredFlagsAndRepeatedEnabledDoesNotOverwriteUpdates(){var r=Child("authored",ShadowCastingMode.ShadowsOnly,false);var toggle=root.AddComponent<ShadowlessFighterMaterials>();toggle.Apply();toggle.Apply();toggle.Restore();Assert.AreEqual(ShadowCastingMode.ShadowsOnly,r.shadowCastingMode);Assert.IsFalse(r.receiveShadows);r.shadowCastingMode=ShadowCastingMode.TwoSided;r.receiveShadows=true;toggle.Restore();Assert.AreEqual(ShadowCastingMode.TwoSided,r.shadowCastingMode);Assert.IsTrue(r.receiveShadows);}
  [Test]public void NewChildAndRuntimeMaterialReplacementSurviveRepeatedToggle(){var first=Child("first",ShadowCastingMode.Off,false);var toggle=root.AddComponent<ShadowlessFighterMaterials>();toggle.Apply();var late=Child("late",ShadowCastingMode.TwoSided,true);first.sharedMaterial=replacement;toggle.Apply();Assert.AreSame(replacement,first.sharedMaterial);Assert.AreEqual(ShadowCastingMode.Off,late.shadowCastingMode);toggle.Restore();Assert.AreSame(replacement,first.sharedMaterial);Assert.AreEqual(ShadowCastingMode.Off,first.shadowCastingMode);Assert.IsFalse(first.receiveShadows);Assert.AreEqual(ShadowCastingMode.TwoSided,late.shadowCastingMode);Assert.IsTrue(late.receiveShadows);}
  [Test]public void ExternalFlagUpdatesAndDisableReleaseOwnedOverrides(){var r=Child("external",ShadowCastingMode.On,true);var toggle=root.AddComponent<ShadowlessFighterMaterials>();toggle.Apply();r.shadowCastingMode=ShadowCastingMode.TwoSided;r.receiveShadows=true;toggle.Restore();Assert.AreEqual(ShadowCastingMode.TwoSided,r.shadowCastingMode);Assert.IsTrue(r.receiveShadows);toggle.Apply();toggle.enabled=false;Assert.AreEqual(ShadowCastingMode.TwoSided,r.shadowCastingMode);Assert.IsTrue(r.receiveShadows);}
 }
}
